1	import { Server as SocketIOServer } from "socket.io";
2	import type { Server as HttpServer } from "node:http";
3	import { clerkClient } from "@clerk/express";
4	import { logger } from "./logger";
5	
6	let io: SocketIOServer | null = null;
7	
8	export function initSocketIO(httpServer: HttpServer): SocketIOServer {
9	  io = new SocketIOServer(httpServer, {
10	    cors: { origin: true, credentials: true },
11	    transports: ["websocket", "polling"],
12	  });
13	
14	  // Auth middleware — runs before "connection" fires
15	  io.use(async (socket, next) => {
16	    try {
17	      const token = socket.handshake.auth?.token as string | undefined;
18	      const userId = socket.handshake.auth?.userId as string | undefined;
19	
20	      // Agent bypass (dev / automated tests)
21	      const bypassKey = process.env.AGENT_BYPASS_KEY;
22	      if (bypassKey && socket.handshake.auth?.agentKey === bypassKey) {
23	        socket.data.userId = userId ?? "agent-test-user";
24	        return next();
25	      }
26	
27	      // No Clerk secret in dev → trust the userId from the handshake
28	      if (!process.env.CLERK_SECRET_KEY) {
29	        socket.data.userId = userId ?? "anon";
30	        return next();
31	      }
32	
33	      if (!token) return next(new Error("auth:no_token"));
34	
35	      // clerkClient.verifyToken is available on @clerk/express v2+
36	      const payload = await (clerkClient as any).verifyToken(token) as { sub: string };
37	      socket.data.userId = payload.sub;
38	      next();
