router.post("/dm/send", requireAuth, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;
  const { senderName, recipientUserId, body, contextType, contextId } = req.body ?? {};
  if (!senderName || !recipientUserId || !body) {
