import { Router, type IRouter } from "express";
import { desc, eq, or, and, sql, inArray } from "drizzle-orm";
import { db, directMessagesTable, notificationsTable, userProfilesTable } from "@workspace/db";
import { requireAuth, getCurrentUserId } from "../lib/auth";
import { socketEmit, dmRoom, getPresence } from "../lib/socket";

const router: IRouter = Router();

function formatMsg(r: typeof directMessagesTable.$inferSelect) {
  return {
    ...r,
    createdAt: r.createdAt.toISOString(),
    readAt: r.readAt ? r.readAt.toISOString() : null,
  };
}

// GET /dm/threads — list my conversations, grouped by "other user"
router.get("/dm/threads", requireAuth, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;

  const rows = await db.select().from(directMessagesTable)
    .where(or(eq(directMessagesTable.senderUserId, userId), eq(directMessagesTable.recipientUserId, userId)))
    .orderBy(desc(directMessagesTable.createdAt));

  const threadMap = new Map<string, {
    otherUserId: string;
    otherUserName: string;
    lastMessage: ReturnType<typeof formatMsg>;
    unread: number;
  }>();

  for (const r of rows) {
    const otherUserId = r.senderUserId === userId ? r.recipientUserId : r.senderUserId;
    const existing = threadMap.get(otherUserId);
    const isIncoming = r.recipientUserId === userId;
    const isUnread = isIncoming && !r.readAt;
    if (!existing) {
      threadMap.set(otherUserId, {
        otherUserId,
        otherUserName: r.senderUserId === userId ? "—" : r.senderName,
        lastMessage: formatMsg(r),
        unread: isUnread ? 1 : 0,
      });
    } else if (isUnread) {
      existing.unread += 1;
    }
  }

  // Fill in names for threads where the latest message is from me
  for (const thread of threadMap.values()) {
    if (thread.otherUserName === "—") {
      const fromOther = rows.find(r => r.senderUserId === thread.otherUserId);
      if (fromOther) thread.otherUserName = fromOther.senderName;
      else thread.otherUserName = "Vartotojas";
    }
  }

  // Fetch avatars for all other users from userProfilesTable
  const otherIds = [...threadMap.keys()];
  const imageMap = new Map<string, string | null>();
  if (otherIds.length > 0) {
    const profiles = await db
      .select({ userId: userProfilesTable.userId, imageUrl: userProfilesTable.imageUrl })
      .from(userProfilesTable)
      .where(inArray(userProfilesTable.userId, otherIds));
    for (const p of profiles) imageMap.set(p.userId, p.imageUrl);
  }

  const threads = [...threadMap.values()].map(t => ({
    ...t,
    otherUserImageUrl: imageMap.get(t.otherUserId) ?? null,
  }));

  res.json(threads);
});

// GET /dm/thread/:otherUserId — all messages between me and otherUserId
router.get("/dm/thread/:otherUserId", requireAuth, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;
  const otherUserId = String(req.params.otherUserId);

  const rows = await db.select().from(directMessagesTable)
    .where(or(
      and(eq(directMessagesTable.senderUserId, userId), eq(directMessagesTable.recipientUserId, otherUserId)),
      and(eq(directMessagesTable.senderUserId, otherUserId), eq(directMessagesTable.recipientUserId, userId)),
    ))
    .orderBy(directMessagesTable.createdAt);

  // Mark incoming messages as read and signal all of the user's tabs to
  // refresh their unread badge immediately (Test 3: multi-tab sync).
  const updated = await db.update(directMessagesTable).set({ readAt: new Date() })
    .where(and(
      eq(directMessagesTable.senderUserId, otherUserId),
      eq(directMessagesTable.recipientUserId, userId),
      sql`${directMessagesTable.readAt} IS NULL`,
    )).returning({ id: directMessagesTable.id });

  if (updated.length > 0) {
    socketEmit(`inbox_${userId}`, "unread_update", {});
  }

  res.json(rows.map(formatMsg));
});

// POST /dm/send — send a direct message
router.post("/dm/send", requireAuth, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;
  const { senderName, recipientUserId, body, contextType, contextId } = req.body ?? {};
  if (!senderName || !recipientUserId || !body) {
    res.status(400).json({ error: "senderName, recipientUserId, body required" }); return;
  }

  const [msg] = await db.insert(directMessagesTable).values({
    senderUserId: userId,
    senderName,
    recipientUserId,
    body,
    contextType: contextType ?? null,
    contextId: contextId ?? null,
  }).returning();

  // Notification for recipient
  await db.insert(notificationsTable).values({
    userId: recipientUserId,
    type: "message",
    title: `Nauja žinutė nuo ${senderName}`,
    body: body.length > 100 ? body.slice(0, 97) + "…" : body,
    link: `/messages?u=${userId}`,
  }).catch(() => {});

  // Real-time: push to the shared DM room and trigger an unread badge refresh
  const formatted = formatMsg(msg);
  socketEmit(dmRoom(userId, recipientUserId), "new_message", { type: "dm", message: formatted });
  socketEmit(`inbox_${recipientUserId}`, "unread_update", {});

  res.status(201).json(formatted);
});

// GET /dm/unread-count
router.get("/dm/unread-count", requireAuth, async (req, res): Promise<void> => {
  const userId = getCurrentUserId(req)!;
  const [row] = await db.select({ count: sql<number>`count(*)` }).from(directMessagesTable)
    .where(and(eq(directMessagesTable.recipientUserId, userId), sql`${directMessagesTable.readAt} IS NULL`));
  res.json({ count: Number(row?.count ?? 0) });
});

// GET /dm/presence?userIds=id1,id2
router.get("/dm/presence", requireAuth, (req, res): void => {
  const ids = String(req.query.userIds ?? "")
    .split(",")
    .map(s => s.trim())
    .filter(Boolean)
    .slice(0, 50);
  res.json(getPresence(ids));
});

export default router;

import { Server as SocketIOServer } from "socket.io";
import type { Server as HttpServer } from "node:http";
import { clerkClient } from "@clerk/express";
import { logger } from "./logger";

let io: SocketIOServer | null = null;

const presenceMap = new Map<string, { lastSeen: Date; online: boolean }>();

export function getPresence(userIds: string[]): Record<string, { online: boolean; lastSeen: string }> {
  const result: Record<string, { online: boolean; lastSeen: string }> = {};
  for (const uid of userIds) {
    const p = presenceMap.get(uid);
    result[uid] = p
      ? { online: p.online, lastSeen: p.lastSeen.toISOString() }
      : { online: false, lastSeen: new Date(0).toISOString() };
  }
  return result;
}

export function initSocketIO(httpServer: HttpServer): SocketIOServer {
  io = new SocketIOServer(httpServer, {
    cors: { origin: true, credentials: true },
    transports: ["websocket", "polling"],
  });

  // Auth middleware — runs before "connection" fires
  io.use(async (socket, next) => {
    try {
      const token = socket.handshake.auth?.token as string | undefined;
      const userId = socket.handshake.auth?.userId as string | undefined;

      // Agent bypass (dev / automated tests)
      const bypassKey = process.env.AGENT_BYPASS_KEY;
      if (bypassKey && socket.handshake.auth?.agentKey === bypassKey) {
        socket.data.userId = userId ?? "agent-test-user";
        return next();
      }

      // No Clerk secret in dev → trust the userId from the handshake
      if (!process.env.CLERK_SECRET_KEY) {
        socket.data.userId = userId ?? "anon";
        return next();
      }

      if (!token) return next(new Error("auth:no_token"));

      // clerkClient.verifyToken is available on @clerk/express v2+
      const payload = await (clerkClient as any).verifyToken(token) as { sub: string };
      socket.data.userId = payload.sub;
      next();
    } catch {
      next(new Error("auth:invalid_token"));
    }
  });

  io.on("connection", (socket) => {
    const userId: string = socket.data.userId;

    // Every authenticated user is always subscribed to their own inbox room
    // so that unread_update events reach them regardless of which chat is open.
    socket.join(`inbox_${userId}`);
    presenceMap.set(userId, { lastSeen: new Date(), online: true });
    logger.debug({ userId, id: socket.id }, "socket connected");

    // Clients emit this whenever they open a specific conversation.
    // The server adds the socket to the appropriate narrow room so future
    // new_message events are only delivered to sockets that care about them.
    socket.on("join_rooms", (params: {
      dmUserId?: string;
      courtId?: number;
      playerId?: string;
      gameId?: number;
    }) => {
      if (params.dmUserId) {
        socket.join(dmRoom(userId, params.dmUserId));
      }
      if (params.courtId != null && params.playerId) {
        socket.join(`facility_${params.courtId}_${params.playerId}`);
      }
      if (params.gameId != null) {
        socket.join(`game_${params.gameId}`);
      }
    });

    socket.on("leave_rooms", (params: {
      dmUserId?: string;
      courtId?: number;
      playerId?: string;
      gameId?: number;
    }) => {
      if (params.dmUserId) {
        socket.leave(dmRoom(userId, params.dmUserId));
      }
      if (params.courtId != null && params.playerId) {
        socket.leave(`facility_${params.courtId}_${params.playerId}`);
      }
      if (params.gameId != null) {
        socket.leave(`game_${params.gameId}`);
      }
    });

    socket.on("disconnect", () => {
      // Only mark offline if this was the user's last socket
      const remaining = io?.sockets.sockets;
      const stillOnline = remaining
        ? [...remaining.values()].some(s => s !== socket && s.data.userId === userId)
        : false;
      if (!stillOnline) presenceMap.set(userId, { lastSeen: new Date(), online: false });
      logger.debug({ userId, id: socket.id }, "socket disconnected");
    });
  });

  return io;
}

/** Emit to a room — safe to call even before initSocketIO (silently no-ops). */
export function socketEmit(room: string, event: string, data: unknown): void {
  try { io?.to(room).emit(event, data); } catch { /* ignore */ }
}

/** Canonical DM room name — sorts user IDs so both sides produce the same string. */
export function dmRoom(uid1: string, uid2: string): string {
  return `dm_${[uid1, uid2].sort().join("_")}`;
}

interface Props {
  sport?: string | null;
  surface?: string | null;
  surfaceSpeed?: string | null;
  surfaceBounce?: string | null;
}

const SURFACE_LABELS: Record<string, string> = {
  hard: "Kietas",
  clay: "Molis",
  grass: "Žolė",
  carpet: "Kilimas",
  artificial_grass: "Dirbtinė žolė",
  wood: "Medis",
  rubber: "Guma",
  concrete: "Betonas",
};

const SPEED_LABELS: Record<string, string> = {
  slow: "Lėtas",
  medium: "Vidutinis",
  fast: "Greitas",
};

const BOUNCE_LABELS: Record<string, string> = {
  low: "Žemas",
  medium: "Vidutinis",
  high: "Aukštas",
};

export function SurfaceSpecs({ sport, surface, surfaceSpeed, surfaceBounce }: Props) {
  const surfaceLabel = surface ? (SURFACE_LABELS[surface] ?? surface) : null;
  const isTennisPadel = sport === "tennis" || sport === "padel" || sport === "squash" || sport === "badminton";

  const specs: Array<{ label: string; value: string }> = [];
  if (surfaceLabel) specs.push({ label: "Danga", value: surfaceLabel });
  if (isTennisPadel && surfaceSpeed) specs.push({ label: "Greitis", value: SPEED_LABELS[surfaceSpeed] ?? surfaceSpeed });
  if (isTennisPadel && surfaceBounce) specs.push({ label: "Atšokimas", value: BOUNCE_LABELS[surfaceBounce] ?? surfaceBounce });

  if (specs.length === 0) return null;

  return (
    <div className="flex flex-wrap gap-2">
      {specs.map((s) => (
        <div
          key={s.label}
          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full border bg-muted/30 text-xs font-medium"
        >
          <span className="text-muted-foreground">{s.label}:</span>
          <span className="text-foreground font-semibold">{s.value}</span>
        </div>
      ))}
    </div>
  );
}

