import { Link, useLocation } from "wouter";
import { useState, useEffect, useRef, lazy, Suspense } from "react";
import { useGetStatsSummary, useGetPopularCourts, useListCourts, customFetch, getGetStatsSummaryQueryKey, getGetPopularCourtsQueryKey, getListCourtsQueryKey } from "@workspace/api-client-react";
import { useQuery } from "@tanstack/react-query";
import { Layout } from "@/components/layout";
import { CourtCard } from "@/components/court-card";
import { Card, CardContent, CardHeader, CardTitle, CardDescription, CardFooter } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import { MapPin, ArrowRight, Heart, Landmark, Search, Building2, Mail, Phone, Instagram, Facebook, MessageCircle, CalendarDays, Clock, ChevronDown, ChevronLeft, ChevronRight, TrendingUp, CreditCard, Users, BarChart3, CheckCircle2, Euro, Bell, Trophy, Flame, Eye, X } from "lucide-react";
import { useT, useI18n } from "@/lib/i18n";
import { useIsMobile } from "@/hooks/use-mobile";
import { useFavoritesContext } from "@/lib/FavoritesContext";
import { useUser } from "@clerk/react";
import { SportIcon, sportColor, SportPill, getSportColor, SPORT_LABELS } from "@/components/sport-icon";

// Lazy-loaded: Google Maps SDK is heavy and the map is below the fold.
const CourtMap = lazy(() => import("@/components/court-map").then(m => ({ default: m.CourtMap })));
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { resolveCourtImage } from "@/lib/imageUrl";
import { SPORT_IMAGES } from "@/lib/sport-images";
import { format } from "date-fns";
import { DateCalendar } from "@/components/ui/date-calendar";
import { lt as ltLocale, enUS, ru as ruLocale } from "date-fns/locale";

const HERO_IMAGES = [
  "courts/court_2_bernardinu.webp",
  "courts/padel/padel_court_indoor_1.webp",
  "courts/court_1_seb_arena.webp",
  "courts/football/football_futsal_court_2.webp",
  "courts/court_4_verkiai.webp",
];

type PopularCourt = { id: number; name: string; type: string; city: string; address?: string | null; imageUrl?: string | null; isIndoor?: boolean | null; rating?: number | null; pricePerHour?: number | string | null; minDisplayPrice?: number | null };

interface FeaturedTournament {
  id: number; name: string; sport: string; startDate: string; endDate: string;
  maxParticipants: number; entryFee: number | null; status: string;
  coverPhotoUrl: string | null; registrationCount: number; description: string | null;
  featuredUntil: string | null; isFeatured: boolean;
}

function FeaturedTournamentsSection() {
  const API_BASE = import.meta.env.BASE_URL.replace(/\/$/, "") + "/api";
  const { data, isLoading } = useQuery<FeaturedTournament[]>({
    queryKey: ["featured-tournaments"],
    queryFn: () => customFetch<FeaturedTournament[]>(`${API_BASE}/tournaments?featured=1`),
    staleTime: 300_000,
  });

  if (isLoading) return null;
  const tournaments = (data ?? []).slice(0, 6);
  if (tournaments.length === 0) return null;

  return (
    <section className="py-14 md:py-20 container mx-auto px-4">
      <div className="flex items-end justify-between mb-8">
        <div>
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-primary/15 text-primary text-[11px] font-bold uppercase tracking-wider mb-3">
            <Flame className="w-3.5 h-3.5" /> Aktualūs turnyrai
          </div>
          <h2 className="text-2xl md:text-4xl font-extrabold tracking-tight">Artimiausi turnyrai</h2>
          <p className="text-sm md:text-base text-muted-foreground mt-2">Registruokis ir varžykis geriausiose Lietuvos aikštelėse.</p>
        </div>
        <Link href="/tournaments" className="hidden md:inline-flex items-center gap-1.5 text-sm font-semibold text-primary hover:gap-2 transition-all">
          Visi turnyrai <ArrowRight className="w-4 h-4" />
        </Link>
      </div>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {tournaments.map((t) => (
          <Link key={t.id} href={`/tournaments/${t.id}`}>
            <div className="group relative rounded-2xl border border-border bg-card overflow-hidden hover:border-primary/60 hover:shadow-xl transition-all cursor-pointer h-full">
              <div className="h-32 bg-gradient-to-br from-primary/30 via-primary/15 to-background relative overflow-hidden">
                {t.coverPhotoUrl ? (
                  <img src={resolveCourtImage(t.coverPhotoUrl) ?? undefined} alt={t.name} loading="lazy" decoding="async" className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500" />
                ) : (
                  <div className="w-full h-full flex items-center justify-center">
                    <Trophy className="w-16 h-16 text-primary/30" />
                  </div>
                )}
                <Badge className="absolute top-3 left-3 bg-primary text-primary-foreground shadow-md">
                  <Flame className="w-3 h-3 mr-1"/>Reklamuojamas
                </Badge>
              </div>
              <div className="p-5 space-y-3">
                <h3 className="font-bold text-base leading-tight line-clamp-2 group-hover:text-primary transition-colors">{t.name}</h3>
                {t.description && <p className="text-xs text-muted-foreground line-clamp-2">{t.description}</p>}
                <div className="flex items-center justify-between text-xs text-muted-foreground pt-2 border-t border-border/60">
                  <div className="flex items-center gap-1"><CalendarDays className="w-3.5 h-3.5"/>{new Date(t.startDate).toLocaleDateString("lt-LT", { month: "short", day: "numeric" })}</div>
                  <div className="flex items-center gap-1"><Users className="w-3.5 h-3.5"/>{t.registrationCount}/{t.maxParticipants}</div>
                  {t.entryFee != null && <div className="flex items-center gap-1 font-semibold text-primary"><Euro className="w-3.5 h-3.5"/>{t.entryFee}</div>}
                </div>
              </div>
            </div>
          </Link>
        ))}
      </div>
      <div className="mt-6 text-center md:hidden">
        <Link href="/tournaments" className="inline-flex items-center gap-1.5 text-sm font-semibold text-primary">
          Visi turnyrai <ArrowRight className="w-4 h-4" />
        </Link>
      </div>
    </section>
  );
}

function StarRatingSmall({ rating }: { rating?: number | null }) {
  const t = useT();
  if (!rating) return <span className="text-[10px] text-muted-foreground italic">{t("detail.noReviews")}</span>;
  const full = Math.floor(rating);
  const hasHalf = rating - full >= 0.25 && rating - full < 0.75;
  const empty = 5 - full - (hasHalf ? 1 : 0);
  return (
    <div className="flex items-center gap-1">
      <div className="flex">
        {Array.from({ length: full }).map((_, i) => (
          <span key={`f${i}`} className="text-yellow-400 text-[11px] leading-none">★</span>
        ))}
        {hasHalf && <span className="text-yellow-300 text-[11px] leading-none">★</span>}
        {Array.from({ length: empty }).map((_, i) => (
          <span key={`e${i}`} className="text-muted-foreground/30 text-[11px] leading-none">★</span>
        ))}
      </div>
      <span className="text-xs font-semibold text-foreground">{rating.toFixed(1)}</span>
    </div>
  );
}

function DragScrollRow({ children, className }: { children: React.ReactNode; className?: string }) {
  const ref = useRef<HTMLDivElement>(null);
  const dragging = useRef(false);
  const startX = useRef(0);
  const scrollLeft = useRef(0);

  const scroll = (dir: "left" | "right") => {
    if (!ref.current) return;
    ref.current.scrollBy({ left: dir === "right" ? 320 : -320, behavior: "smooth" });
  };

  return (
    <div className="relative group/carousel">
      {/* Left arrow only — no fade gradient */}
      <button
        type="button"
        onClick={() => scroll("left")}
        className="absolute left-2 top-1/2 -translate-y-1/2 z-20 w-9 h-9 rounded-full bg-background/90 border shadow-md flex items-center justify-center opacity-0 group-hover/carousel:opacity-100 transition-opacity hover:bg-accent"
        aria-label="Scroll left"
      >
        <ChevronLeft className="w-4 h-4" />
      </button>

      <div
        ref={ref}
        className={`flex gap-4 overflow-x-auto snap-x snap-mandatory pb-3 cursor-grab active:cursor-grabbing select-none ${className ?? ""}`}
        style={{ scrollbarWidth: "none", msOverflowStyle: "none" } as React.CSSProperties}
        onMouseDown={(e) => {
          dragging.current = true;
          startX.current = e.pageX - (ref.current?.offsetLeft ?? 0);
          scrollLeft.current = ref.current?.scrollLeft ?? 0;
        }}
        onMouseMove={(e) => {
          if (!dragging.current || !ref.current) return;
          e.preventDefault();
          const x = e.pageX - ref.current.offsetLeft;
          ref.current.scrollLeft = scrollLeft.current - (x - startX.current) * 1.5;
        }}
        onMouseUp={() => { dragging.current = false; }}
        onMouseLeave={() => { dragging.current = false; }}
      >
        {children}
      </div>

      {/* Right arrow only — no fade gradient */}
      <button
        type="button"
        onClick={() => scroll("right")}
        className="absolute right-2 top-1/2 -translate-y-1/2 z-20 w-9 h-9 rounded-full bg-background/90 border shadow-md flex items-center justify-center opacity-0 group-hover/carousel:opacity-100 transition-opacity hover:bg-accent"
        aria-label="Scroll right"
      >
        <ChevronRight className="w-4 h-4" />
      </button>
    </div>
  );
}

function PopularCourtCard({ court }: { court: PopularCourt }) {
  const t = useT();
  const [hovered, setHovered] = useState(false);
  const [btnHovered, setBtnHovered] = useState(false);
  const imgSrc = resolveCourtImage(court.imageUrl, court.type);
  const sportLabel = t(`sports.${court.type}` as never) || court.type;
  const color = getSportColor(court.type);

  return (
    <Card
      className="h-full flex flex-col transition-colors duration-200 group overflow-hidden"
      style={{ borderColor: hovered ? color : undefined }}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
    >
      {imgSrc ? (
        <div className="w-full h-48 overflow-hidden bg-muted relative">
          <img
            src={imgSrc}
            alt={court.name}
            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
            onError={(e) => {
              (e.target as HTMLImageElement).src = `https://ui-avatars.com/api/?name=${encodeURIComponent(court.name)}&background=random&size=400`;
            }}
          />
          {court.isIndoor !== undefined && court.isIndoor !== null && (
            <div className="absolute top-2 right-2 flex gap-1 items-center">
              <span className="text-[10px] font-medium px-2 py-0.5 rounded-full bg-black/60 text-white backdrop-blur-sm">
                {court.isIndoor ? t("card.indoor") : t("card.outdoor")}
              </span>
            </div>
          )}
        </div>
      ) : (
        <div className="w-full h-48 bg-muted flex items-center justify-center">
          <SportIcon sport={court.type} size={40} style={{ color }} />
        </div>
      )}

      <CardHeader className="pb-2">
        <div className="flex justify-between items-start mb-2 gap-2">
          <div className="flex gap-1.5 flex-wrap items-center">
            <SportPill
              sport={court.type}
              variant={hovered ? "solid" : "subtle"}
              className="transition-all duration-200"
            />
            <StarRatingSmall rating={court.rating} />
          </div>
          {(court.minDisplayPrice ?? court.pricePerHour) && (
            <div className="flex items-baseline gap-0.5 shrink-0">
              <span className="text-xs text-muted-foreground">{t("card.from")}</span>
              <span className="text-lg font-bold text-foreground">
                {Math.round(Number(court.minDisplayPrice ?? court.pricePerHour))}€
              </span>
              <span className="text-xs text-muted-foreground">{t("card.perHour")}</span>
            </div>
          )}
        </div>
        <CardTitle
          className="transition-colors duration-200 line-clamp-1 text-base"
          style={{ color: hovered ? color : undefined }}
        >
          {court.name}
        </CardTitle>
        <CardDescription className="flex items-center text-xs">
          <MapPin className="h-3 w-3 mr-1 shrink-0" />
          <span className="truncate">{court.city}{court.address ? ` — ${court.address}` : ""}</span>
        </CardDescription>
      </CardHeader>

      <CardFooter className="pt-0 mt-auto gap-2">
        <Link href={`/courts/${court.id}`} aria-label={t("card.view")}>
          <Button
            variant="outline"
            size="icon"
            className="shrink-0 transition-all duration-200 active:scale-[0.98]"
            title={t("card.view")}
          >
            <Eye className="w-4 h-4" />
          </Button>
        </Link>
        <Link href={`/courts/${court.id}#reserve`} className="flex-1"
          onMouseEnter={() => setBtnHovered(true)}
          onMouseLeave={() => setBtnHovered(false)}
        >
          <Button
            className="w-full transition-all duration-200 active:scale-[0.98] font-semibold"
            style={{ backgroundColor: color, borderColor: color, color: "#fff", ...(btnHovered ? { boxShadow: `0 4px 14px ${color}55` } : {}) }}
          >
            {t("card.reserve")}
          </Button>
        </Link>
      </CardFooter>
    </Card>
  );
}

export default function Home() {
  const t = useT();
  const isMobile = useIsMobile();
  const { isSignedIn } = useUser();
  const { favorites, loading: favLoading } = useFavoritesContext();
  const [heroIdx, setHeroIdx] = useState(0);
  const [loadedHeroImages, setLoadedHeroImages] = useState(() => new Set([0, 1]));
  const ALL_SPORTS = Object.keys(SPORT_LABELS);
  const [activeSports, setActiveSports] = useState<Set<string>>(new Set(ALL_SPORTS));

  const toggleSport = (sport: string) => {
    setActiveSports(prev => {
      const next = new Set(prev);
      if (next.has(sport)) { next.delete(sport); } else { next.add(sport); }
      return next;
    });
  };
  const allActive = activeSports.size === ALL_SPORTS.length;
  const [hoveredStat, setHoveredStat] = useState<string | null>(null);
  const [tappedStat, setTappedStat] = useState<string | null>(null);

  // Search bar state
  const [, setLocation] = useLocation();
  const [searchName, setSearchName] = useState("");
  const [searchSport, setSearchSport] = useState("");
  const [searchCity, setSearchCity] = useState("");
  const [searchDate, setSearchDate] = useState("");
  const [searchTime, setSearchTime] = useState("");
  const [dropdownOpen, setDropdownOpen] = useState(false);
  const searchRef = useRef<HTMLDivElement>(null);
  const [cityDropdownOpen, setCityDropdownOpen] = useState(false);
  const [cityInput, setCityInput] = useState("");
  const cityRef = useRef<HTMLDivElement>(null);
  const [timeDropdownOpen, setTimeDropdownOpen] = useState(false);
  const [timeSlider, setTimeSlider] = useState<number | null>(null);
  const timeRef = useRef<HTMLDivElement>(null);
  const [dateDropdownOpen, setDateDropdownOpen] = useState(false);
  const [searchDateObj, setSearchDateObj] = useState<Date | undefined>(undefined);
  const dateRef = useRef<HTMLDivElement>(null);
  const [showMoreCities, setShowMoreCities] = useState(false);
  const { locale } = useI18n();

  // Time-of-day accent — uses local browser time so it's already location-aware
  const [currentHour, setCurrentHour] = useState(() => new Date().getHours());
  useEffect(() => {
    const tick = setInterval(() => setCurrentHour(new Date().getHours()), 60_000);
    return () => clearInterval(tick);
  }, []);

  const TIME_PALETTES: { label: string; color: string; fg: string }[] = [
    { label: "dawn",      color: "#38bdf8", fg: "#000" }, // 05-09  sky blue
    { label: "morning",   color: "#84cc16", fg: "#000" }, // 10-13  lime (default)
    { label: "afternoon", color: "#f59e0b", fg: "#000" }, // 14-16  warm amber
    { label: "evening",   color: "#f97316", fg: "#000" }, // 17-20  sunset orange
    { label: "night",     color: "#8b5cf6", fg: "#fff" }, // 21-04  indigo/night
  ];
  const timePalette =
    currentHour >= 5  && currentHour < 10 ? TIME_PALETTES[0] :
    currentHour >= 10 && currentHour < 14 ? TIME_PALETTES[1] :
    currentHour >= 14 && currentHour < 17 ? TIME_PALETTES[2] :
    currentHour >= 17 && currentHour < 21 ? TIME_PALETTES[3] :
    TIME_PALETTES[4];

  const timeAccent = timePalette.color;

  const accentColor = searchSport ? (sportColor[searchSport] ?? timeAccent) : timeAccent;
  function contrastText(hex: string) {
    const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    return (0.299*r + 0.587*g + 0.114*b) / 255 > 0.55 ? "#000" : "#fff";
  }
  const accentFg = contrastText(accentColor);

  function handleSearch() {
    const params = new URLSearchParams();
    if (searchName.trim()) params.set("name", searchName.trim());
    if (searchSport) params.set("type", searchSport);
    if (searchCity) params.set("city", searchCity);
    if (searchDate) params.set("date", searchDate);
    if (searchTime) params.set("time", searchTime);
    setLocation(`/courts${params.toString() ? "?" + params.toString() : ""}`);
  }

  useEffect(() => {
    function handleClick(e: MouseEvent) {
      if (searchRef.current && !searchRef.current.contains(e.target as Node)) {
        setDropdownOpen(false);
      }
      if (cityRef.current && !cityRef.current.contains(e.target as Node)) {
        setCityDropdownOpen(false);
      }
      if (timeRef.current && !timeRef.current.contains(e.target as Node)) {
        setTimeDropdownOpen(false);
      }
      if (dateRef.current && !dateRef.current.contains(e.target as Node)) {
        setDateDropdownOpen(false);
      }
    }
    document.addEventListener("mousedown", handleClick);
    return () => document.removeEventListener("mousedown", handleClick);
  }, []);

  useEffect(() => {
    const interval = setInterval(() => {
      setHeroIdx((i) => (i + 1) % HERO_IMAGES.length);
    }, 5000);
    return () => clearInterval(interval);
  }, []);

  // Preload the next hero image before we need to show it
  useEffect(() => {
    const nextIdx = (heroIdx + 1) % HERO_IMAGES.length;
    setLoadedHeroImages(prev => {
      if (prev.has(nextIdx)) return prev;
      const s = new Set(prev);
      s.add(nextIdx);
      return s;
    });
  }, [heroIdx]);

  const base = import.meta.env.BASE_URL.replace(/\/$/, "");

  const { data: stats, isLoading: statsLoading } = useGetStatsSummary({
    query: { queryKey: getGetStatsSummaryQueryKey(), staleTime: 300_000 },
  });
  const { data: popularCourts, isLoading: popularLoading } = useGetPopularCourts({
    query: { queryKey: getGetPopularCourtsQueryKey(), staleTime: 300_000 },
  });
  const { data: courts, isLoading: courtsLoading } = useListCourts(undefined, {
    query: { queryKey: getListCourtsQueryKey(), staleTime: 300_000 },
  });

  const filteredCourts = searchName.trim().length >= 2
    ? (courts ?? [])
        .filter(c => c.name.toLowerCase().includes(searchName.trim().toLowerCase()))
        .slice(0, 7)
    : [];

  const uniqueCities = [...new Set((courts ?? []).map(c => c.city).filter((c): c is string => !!c))].sort();

  // City combobox helpers
  const cityCounts = (courts ?? []).reduce<Record<string, number>>((acc, c) => {
    if (c.city) acc[c.city] = (acc[c.city] ?? 0) + 1;
    return acc;
  }, {});
  const TOP_N = 5;
  const popularCities = [...uniqueCities].sort((a, b) => (cityCounts[b] ?? 0) - (cityCounts[a] ?? 0)).slice(0, TOP_N);
  const otherCities = uniqueCities.filter(c => !popularCities.includes(c));
  const cityFilter = cityInput.trim().toLowerCase();
  const filteredPopular = popularCities.filter(c => !cityFilter || c.toLowerCase().includes(cityFilter));
  const filteredOther = otherCities.filter(c => !cityFilter || c.toLowerCase().includes(cityFilter));

  const heroLines = t("home.hero.title").split("\n");

  return (
    <Layout>
      {/* Hero Section — split layout */}
      <section className="bg-background text-foreground">
        <div className="flex lg:pl-[max(0px,calc((100vw-64rem)/2))] xl:pl-[max(0px,calc((100vw-80rem)/2))] 2xl:pl-[max(0px,calc((100vw-96rem)/2))]">

          {/* ── LEFT PANEL: search form ── */}
          <div className="relative z-10 w-full md:w-[400px] lg:w-[440px] xl:w-[480px] flex-shrink-0 flex flex-col justify-start px-5 sm:px-6 lg:pl-4 lg:pr-10 pt-6 pb-6 lg:pt-12 lg:pb-14">
            {/* subtle top-left glow */}
            <div className="absolute inset-0 pointer-events-none opacity-20 bg-[radial-gradient(ellipse_at_top_left,_var(--tw-gradient-stops))] from-primary/50 via-transparent to-transparent" />

            {/* Multi-row search widget */}
              <div className="w-full space-y-2.5 sm:space-y-2" ref={searchRef}>

              {/* Row 1: Court name with autocomplete */}
              <div className="relative w-full max-w-sm">
                <div className="flex items-center gap-3 bg-muted/70 dark:bg-white/20 dark:backdrop-blur-md border border-border rounded-xl px-4 py-3 transition-all"
                  style={{ borderColor: (dropdownOpen || searchName) ? accentColor : undefined }}
                >
                  <Search className="h-4 w-4 shrink-0 text-muted-foreground dark:text-white/75" style={{ color: (dropdownOpen || searchName) ? accentColor : undefined }} />
                  <input
                    type="text"
                    placeholder="Ieškoti aikštelės pagal pavadinimą..."
                    value={searchName}
                    onChange={e => { setSearchName(e.target.value); setDropdownOpen(true); }}
                    onFocus={() => setDropdownOpen(true)}
                    onKeyDown={e => e.key === "Enter" && handleSearch()}
                    className="bg-transparent flex-1 text-foreground dark:text-white placeholder:text-muted-foreground dark:placeholder:text-white/65 outline-none text-sm"
                  />
                  {searchName && (
                    <button onClick={() => setSearchName("")} className="text-muted-foreground/60 hover:text-muted-foreground dark:text-white/40 dark:hover:text-white/70 text-lg leading-none">×</button>
                  )}
                </div>
                {/* Autocomplete dropdown */}
                {dropdownOpen && filteredCourts.length > 0 && (
                  <div className="absolute top-full left-0 right-0 mt-1 bg-card dark:bg-zinc-900/95 backdrop-blur border border-border dark:border-white/10 rounded-xl overflow-hidden shadow-2xl z-50">
                    {filteredCourts.map(court => (
                      <Link
                        key={court.id}
                        href={`/courts/${court.id}`}
                        onClick={() => { setSearchName(""); setDropdownOpen(false); }}
                      >
                        <div className="flex items-center gap-3 px-4 py-3 hover:bg-muted dark:hover:bg-white/10 transition-colors cursor-pointer border-b border-border dark:border-white/5 last:border-b-0">
                          <div className="w-7 h-7 rounded-full flex items-center justify-center shrink-0" style={{ background: `${getSportColor(court.type)}22` }}>
                            <SportIcon sport={court.type} size={14} strokeWidth={2} style={{ color: getSportColor(court.type) }} />
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="text-sm font-medium text-foreground dark:text-white truncate">{court.name}</p>
                            <p className="text-xs text-muted-foreground dark:text-white/45">{court.city}</p>
                          </div>
                          {court.rating != null && (
                            <div className="flex items-center gap-1 shrink-0">
                              <span className="text-yellow-400 text-xs">★</span>
                              <span className="text-xs text-muted-foreground dark:text-white/60 font-medium">{Number(court.rating).toFixed(1)}</span>
                            </div>
                          )}
                        </div>
                      </Link>
                    ))}
                  </div>
                )}
              </div>

              {/* Row 2: Sport + city */}
              <div className="grid grid-cols-2 gap-2 sm:flex sm:items-center">
                <DropdownMenu>
                  <DropdownMenuTrigger asChild>
                    <button className="flex items-center gap-2 px-3 py-2 rounded-xl border border-border bg-muted/70 dark:bg-white/20 dark:text-white text-sm font-medium transition-colors w-full">
                      <SportIcon sport={searchSport || "tennis"} size={14} strokeWidth={2} />
                      <span className="truncate">
                        {searchSport ? SPORT_LABELS[searchSport] : "Sporto šaka"}
                      </span>
                      <ChevronDown className="h-4 w-4 opacity-60" />
                    </button>
                  </DropdownMenuTrigger>
                  <DropdownMenuContent align="start" className="w-56">
                    <DropdownMenuItem onClick={() => setSearchSport("")}>
                      Visi sportai
                    </DropdownMenuItem>
                    {ALL_SPORTS.map(sport => {
                      const color = getSportColor(sport);
                      const active = searchSport === sport;
                      return (
                        <DropdownMenuItem
                          key={sport}
                          onClick={() => setSearchSport(active ? "" : sport)}
                          className="flex items-center gap-2"
                        >
                          <span
                            className="w-4 h-4 rounded-full flex items-center justify-center shrink-0"
                            style={{ background: color }}
                          >
                            <SportIcon sport={sport} size={10} strokeWidth={2} style={{ color: "#fff" }} />
                          </span>
                          <span className="flex-1">{SPORT_LABELS[sport]}</span>
                          {active && <span className="text-xs text-primary font-semibold">✓</span>}
                        </DropdownMenuItem>
                      );
                    })}
                  </DropdownMenuContent>
                </DropdownMenu>

                <div className="relative w-full min-w-0" ref={cityRef}>
                  <div
                    className="flex items-center gap-2 bg-muted/70 dark:bg-white/20 dark:backdrop-blur-md border border-border rounded-xl px-3 py-2.5 cursor-text transition-all"
                    style={{ borderColor: (cityDropdownOpen || searchCity) ? accentColor : undefined }}
                    onClick={() => setCityDropdownOpen(true)}
                  >
                    <MapPin className="h-3.5 w-3.5 shrink-0 text-muted-foreground dark:text-white/75" style={{ color: (cityDropdownOpen || searchCity) ? accentColor : undefined }} />
                    <input
                      type="text"
                      value={searchCity ? searchCity : cityInput}
                      placeholder="Miestas"
                      readOnly={isMobile}
                      onFocus={() => { setCityDropdownOpen(true); if (searchCity) { setCityInput(""); } }}
                      onChange={isMobile ? undefined : e => {
                        setCityInput(e.target.value);
                        setSearchCity("");
                        setCityDropdownOpen(true);
                      }}
                      className="bg-transparent text-sm text-foreground dark:text-white placeholder:text-muted-foreground dark:placeholder:text-white/65 outline-none flex-1 w-full min-w-0"
                    />
                    {searchCity && (
                      <button
                        onClick={e => { e.stopPropagation(); setSearchCity(""); setCityInput(""); }}
                        className="text-muted-foreground/60 hover:text-muted-foreground dark:text-white/40 dark:hover:text-white/70 text-lg leading-none shrink-0"
                      >×</button>
                    )}
                  </div>

                  {cityDropdownOpen && (
                    <div className="absolute top-full left-0 right-0 mt-1 bg-card dark:bg-zinc-900/96 backdrop-blur border border-border dark:border-white/10 rounded-xl overflow-hidden shadow-2xl z-50 max-h-64 overflow-y-auto">
                      {/* All cities option */}
                      <button
                        onMouseDown={e => e.preventDefault()}
                        onClick={() => { setSearchCity(""); setCityInput(""); setCityDropdownOpen(false); }}
                        className="w-full text-left px-4 py-2.5 text-sm transition-colors hover:bg-muted dark:hover:bg-white/10 flex items-center gap-2 text-muted-foreground dark:text-white/60"
                        style={{ color: !searchCity && !cityInput ? accentColor : undefined, fontWeight: !searchCity && !cityInput ? "600" : "400" }}
                      >
                        <MapPin className="h-3.5 w-3.5 shrink-0" />
                        Visi miestai
                      </button>

                      {/* Popular cities */}
                      {filteredPopular.length > 0 && (
                        <>
                          <div className="px-4 py-1 text-[10px] font-semibold text-muted-foreground/50 dark:text-white/30 uppercase tracking-widest border-t border-border dark:border-white/5">
                            Populiariausi
                          </div>
                          {filteredPopular.map(city => (
                            <button
                              key={city}
                              onMouseDown={e => e.preventDefault()}
                              onClick={() => { setSearchCity(city ?? ""); setCityInput(""); setCityDropdownOpen(false); }}
                              className="w-full text-left px-4 py-2.5 text-sm transition-colors hover:bg-muted dark:hover:bg-white/10 flex items-center justify-between text-foreground dark:text-white/80"
                              style={searchCity === city ? { color: accentColor, fontWeight: "600", background: accentColor + "18" } : undefined}
                            >
                              <span>{city}</span>
                              <span className="text-xs text-muted-foreground/50 dark:text-white/30 tabular-nums">{city ? (cityCounts[city] ?? 0) : 0}</span>
                            </button>
                          ))}
                        </>
                      )}

                      {/* Other cities — collapsed behind "More" button when not typing */}
                      {filteredOther.length > 0 && (
                        <>
                          {(showMoreCities || cityInput.length > 0) ? (
                            <>
                              <div className="px-4 py-1 text-[10px] font-semibold text-muted-foreground/50 dark:text-white/30 uppercase tracking-widest border-t border-border dark:border-white/5">
                                Kiti miestai
                              </div>
                              {filteredOther.map(city => (
                                <button
                                  key={city}
                                  onMouseDown={e => e.preventDefault()}
                                  onClick={() => { setSearchCity(city ?? ""); setCityInput(""); setCityDropdownOpen(false); setShowMoreCities(false); }}
                                  className="w-full text-left px-4 py-2.5 text-sm transition-colors hover:bg-muted dark:hover:bg-white/10 flex items-center justify-between text-foreground dark:text-white/80"
                                  style={searchCity === city ? { color: accentColor, fontWeight: "600", background: accentColor + "18" } : undefined}
                                >
                                  <span>{city}</span>
                                  <span className="text-xs text-muted-foreground/50 dark:text-white/30 tabular-nums">{city ? (cityCounts[city] ?? 0) : 0}</span>
                                </button>
                              ))}
                              <button
                                onMouseDown={e => e.preventDefault()}
                                onClick={() => setShowMoreCities(false)}
                                className="w-full text-left px-4 py-2 text-xs text-muted-foreground/50 hover:text-muted-foreground dark:text-white/30 dark:hover:text-white/60 border-t border-border dark:border-white/5 flex items-center gap-1"
                              >
                                <ChevronDown className="h-3 w-3 rotate-180" /> Mažiau
                              </button>
                            </>
                          ) : (
                            <button
                              onMouseDown={e => e.preventDefault()}
                              onClick={() => setShowMoreCities(true)}
                              className="w-full text-left px-4 py-2.5 text-xs text-muted-foreground/50 hover:text-muted-foreground dark:text-white/40 dark:hover:text-white/70 border-t border-border dark:border-white/5 flex items-center gap-1 transition-colors"
                            >
                              <ChevronDown className="h-3 w-3" /> Daugiau miestų ({filteredOther.length})
                            </button>
                          )}
                        </>
                      )}

                      {filteredPopular.length === 0 && filteredOther.length === 0 && (
                        <div className="px-4 py-3 text-sm text-muted-foreground dark:text-white/40 text-center">Nerasta miestų</div>
                      )}
                    </div>
                  )}
                </div>
              </div>

              {/* Row 3: Date + Time */}
              <div className="grid grid-cols-2 gap-2">
                <div className="relative w-full min-w-0" ref={dateRef}>
                  <button
                    onClick={() => setDateDropdownOpen(v => !v)}
                    className="flex w-full items-center gap-2 bg-muted/70 dark:bg-white/20 dark:backdrop-blur-md border border-border rounded-xl px-3 py-2.5 transition-colors whitespace-nowrap justify-between"
                    style={{ borderColor: dateDropdownOpen ? accentColor : undefined }}
                  >
                    <span className="flex items-center gap-2 min-w-0">
                      <CalendarDays className="h-3.5 w-3.5 shrink-0 text-muted-foreground dark:text-white/75" style={{ color: (dateDropdownOpen || searchDateObj) ? accentColor : undefined }} />
                      <span className="text-sm text-foreground dark:text-white truncate">
                        {searchDateObj ? format(searchDateObj, "d MMM", { locale: locale === "lt" ? ltLocale : locale === "ru" ? ruLocale : enUS }) : "Data"}
                      </span>
                    </span>
                    {searchDateObj && (
                      <span
                        onClick={e => { e.stopPropagation(); setSearchDateObj(undefined); setSearchDate(""); }}
                        className="text-muted-foreground/60 hover:text-muted-foreground dark:text-white/40 dark:hover:text-white/70 text-lg leading-none ml-1 shrink-0"
                      >×</span>
                    )}
                  </button>

                  {dateDropdownOpen && (
                    <>
                      <div className="sm:hidden fixed inset-0 bg-black/60 backdrop-blur-sm z-40" onClick={() => setDateDropdownOpen(false)} />
                      <div className="fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-50 w-[min(280px,calc(100vw-1.5rem))] sm:absolute sm:top-full sm:left-0 sm:translate-x-0 sm:translate-y-0 sm:mt-1 sm:w-[252px]">
                        <DateCalendar
                          selected={searchDateObj}
                          onSelect={(d) => { setSearchDateObj(d); setSearchDate(format(d, "yyyy-MM-dd")); setDateDropdownOpen(false); }}
                          onClose={() => setDateDropdownOpen(false)}
                          accentColor={accentColor}
                          accentFg={accentFg}
                          locale={locale}
                        />
                      </div>
                    </>
                  )}
                </div>

                <div className="relative w-full min-w-0" ref={timeRef}>
                  <button
                    onClick={() => setTimeDropdownOpen(v => !v)}
                    className="flex w-full items-center gap-2 bg-muted/70 dark:bg-white/20 dark:backdrop-blur-md border border-border rounded-xl px-3 py-2.5 transition-colors whitespace-nowrap justify-between"
                    style={{ borderColor: timeDropdownOpen ? accentColor : undefined }}
                  >
                    <span className="flex items-center gap-2 min-w-0">
                      <Clock className="h-3.5 w-3.5 shrink-0 text-muted-foreground dark:text-white/75" style={{ color: (timeDropdownOpen || timeSlider !== null) ? accentColor : undefined }} />
                      <span className="text-sm text-foreground dark:text-white truncate">
                        {timeSlider !== null ? `${String(timeSlider).padStart(2, "0")}:00` : "Laikas"}
                      </span>
                    </span>
                    {timeSlider !== null && (
                      <span
                        onClick={e => { e.stopPropagation(); setTimeSlider(null); setSearchTime(""); }}
                        className="text-muted-foreground/60 hover:text-muted-foreground dark:text-white/40 dark:hover:text-white/70 text-lg leading-none ml-1 shrink-0"
                      >×</span>
                    )}
                  </button>

                  {timeDropdownOpen && (
                    <>
                      {/* Mobile backdrop */}
                      <div
                        className="sm:hidden fixed inset-0 bg-black/60 backdrop-blur-sm z-40"
                        onClick={() => setTimeDropdownOpen(false)}
                      />
                      <div className="
                        fixed left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 z-50 w-[min(280px,calc(100vw-1.5rem))]
                        sm:absolute sm:top-full sm:right-0 sm:left-auto sm:translate-x-0 sm:translate-y-0 sm:mt-1 sm:w-56
                        bg-popover text-popover-foreground border border-border rounded-xl p-3 shadow-2xl
                      ">
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">Pradžios laikas</span>
                        <div className="flex items-center gap-1.5">
                          {timeSlider !== null && (
                            <button onClick={() => { setTimeSlider(null); setSearchTime(""); }} className="text-[10px] hover:underline" style={{ color: accentColor }}>Išvalyti</button>
                          )}
                          <button onClick={() => setTimeDropdownOpen(false)} className="p-0.5 rounded text-muted-foreground hover:text-foreground hover:bg-accent transition-colors">
                            <X className="h-3.5 w-3.5" />
                          </button>
                        </div>
                      </div>

                      <div className="text-center mb-2">
                        <span className="text-2xl font-bold tabular-nums">
                          {timeSlider !== null ? `${String(timeSlider).padStart(2, "0")}:00` : "--:--"}
                        </span>
                      </div>

                      <div className="relative px-0.5">
                        <input
                          type="range" min={6} max={23} step={1} value={timeSlider ?? 9}
                          onChange={e => { const h = Number(e.target.value); setTimeSlider(h); setSearchTime(`${String(h).padStart(2, "0")}:00`); }}
                          onMouseDown={() => { if (timeSlider === null) setTimeSlider(9); }}
                          className="time-slider w-full h-1.5 rounded-full appearance-none cursor-pointer"
                          style={{ background: timeSlider !== null ? `linear-gradient(to right, ${accentColor} 0%, ${accentColor} ${(((timeSlider - 6) / 17) * 100).toFixed(1)}%, hsl(var(--muted)) ${(((timeSlider - 6) / 17) * 100).toFixed(1)}%, hsl(var(--muted)) 100%)` : "hsl(var(--muted))" }}
                        />
                        <div className="flex justify-between mt-1.5">
                          {[6, 10, 14, 18, 22].map(h => (
                            <button key={h} onClick={() => { setTimeSlider(h); setSearchTime(`${String(h).padStart(2, "0")}:00`); }}
                              className="text-[9px] tabular-nums transition-colors text-muted-foreground"
                              style={{ color: timeSlider === h ? accentColor : undefined, fontWeight: timeSlider === h ? "700" : "400" }}
                            >{h}:00</button>
                          ))}
                        </div>
                      </div>

                      <button onClick={() => setTimeDropdownOpen(false)} className="mt-3 w-full py-1.5 rounded-lg text-xs font-semibold transition-colors"
                        style={{ background: accentColor, color: accentFg }}>
                        Patvirtinti
                      </button>
                      </div>
                    </>
                  )}
                </div>
              </div>

              {/* Row 4: Search */}
              <div className="w-full">
                <button
                  onClick={handleSearch}
                  className="flex w-full items-center justify-center gap-2 px-5 py-2.5 rounded-xl text-sm font-semibold transition-all shrink-0"
                  style={{ background: accentColor, color: accentFg, boxShadow: `0 0 16px ${accentColor}55` }}
                >
                  <Search className="h-4 w-4" />
                  Ieškoti
                </button>
              </div>
            </div>
          </div>

          {/* ── RIGHT PANEL: rotating court photo ── */}
          <div className="hidden md:block flex-1 relative overflow-hidden">
            {HERO_IMAGES.map((img, i) => {
              if (!loadedHeroImages.has(i)) return null;
              return (
                <img
                  key={img}
                  src={`${base}/${img}`}
                  loading={i === 0 ? "eager" : "lazy"}
                  fetchPriority={i === 0 ? "high" : "auto"}
                  decoding="async"
                  className="absolute inset-0 w-full h-full object-cover"
                  style={{
                    opacity: i === heroIdx ? 1 : 0,
                    transition: "opacity 1.6s ease-in-out",
                    zIndex: i === heroIdx ? 1 : 0,
                  }}
                  aria-hidden
                />
              );
            })}
            {/* Gradient fade on the left edge to blend with the search panel */}
            <div className="absolute inset-y-0 left-0 w-24 bg-gradient-to-r from-background to-transparent z-10 pointer-events-none" />
            {/* Dark scrim over the bottom ~60% so text is always readable */}
            <div className="absolute inset-x-0 bottom-0 h-3/4 bg-gradient-to-t from-black/75 via-black/30 to-transparent z-10 pointer-events-none" />
            {/* Heading + subtitle — always white since it sits over the photo */}
            <div className="absolute left-8 right-8 bottom-12 z-20" style={{ color: "white" }}>
              <h1 className="text-4xl lg:text-5xl xl:text-6xl font-bold tracking-tight mb-3 text-balance leading-tight drop-shadow-lg" style={{ color: "white" }}>
                {(() => {
                  const [line1, line2] = heroLines;
                  const isEnglishTop = line1?.toLowerCase().includes("find your court");
                  const top = isEnglishTop ? line2 : line1;
                  const bottom = isEnglishTop ? line1 : line2;
                  return (
                    <>
                      {top}
                      <br />
                      <span className="text-primary">{bottom}</span>
                    </>
                  );
                })()}
              </h1>
              <p className="text-sm text-white/75 max-w-sm leading-relaxed drop-shadow">
                {t("home.hero.subtitle")}
              </p>
            </div>
            {/* Slide indicator dots */}
            <div className="absolute bottom-6 right-6 z-20 flex gap-1.5 pointer-events-none">
              {HERO_IMAGES.map((_, i) => (
                <span
                  key={i}
                  className="w-1.5 h-1.5 rounded-full transition-all duration-300 pointer-events-none"
                  style={{ background: i === heroIdx ? accentColor : "rgba(255,255,255,0.35)", transform: i === heroIdx ? "scale(1.4)" : "scale(1)" }}
                  aria-hidden
                />
              ))}
            </div>
          </div>

        </div>
      </section>

      {/* Stats Bar */}
      <div className="border-t border-b bg-muted/20">
        <div className="container mx-auto px-4 py-3">
